const faqs=[['Os perfumes são originais?','Sim. A comunicação da loja destaca perfumes originais e a página reforça autenticidade e atendimento consultivo.'],['Como compro?','Clique em Comprar em qualquer perfume. O WhatsApp abre com uma mensagem pronta indicando o perfume escolhido.'],['Atendem quais regiões?','SJP, CWB e Itapoá SC, conforme informado no Instagram da loja.'],['Tem entrega?','A disponibilidade, valores e prazos devem ser confirmados diretamente no WhatsApp.'],['Posso pedir indicação?','Sim. O atendimento pelo WhatsApp pode ajudar com perfil olfativo, ocasião e intensidade desejada.']];export const metadata={title:'FAQ'};export default function FAQ(){return <section className="mx-auto max-w-4xl px-4 py-14"><h1 className="mb-8 font-serif text-5xl">Perguntas frequentes</h1><div className="space-y-4">{faqs.map(([q,a])=><details key={q} className="lux-card rounded-2xl p-6"><summary className="cursor-pointer font-serif text-2xl">{q}</summary><p className="mt-3 text-coffee/70">{a}</p></details>)}</div></section>}
